            long minForD = (d == 1) ? 1 : (long) Math.pow(10, d - 1);
            long maxForD = (long) Math.pow(10, d) - 1;

            // The range for d-digit numbers is [minForD, maxForD]
            // The intersection with [l, r] is [max(l, minForD), min(r, maxForD)]
            long lo = Math.max(l, minForD);
            long hi = Math.min(r, maxForD);

            if (lo > hi) {
                continue; // No d-digit numbers in [l, r]
            }

            // Add the boundaries of the intersection
            candidates.add(lo);
            candidates.add(hi);

            // The vertex of the parabola for d digits is at (10^d - 1) / 2
            long vertex = ((long) Math.pow(10, d) - 1) / 2;

            // Check vertex and its neighbors
            for (long v = vertex - 2; v <= vertex + 2; v++) {
                if (v >= lo && v <= hi) {
                    candidates.add(v);
                }
            }
        }

        // Now compute the maximum weight among all candidates
        long maxWeightFinal = 0;
        for (long n : candidates) {
            if (n < l || n > r) {
                continue;
            }
            long weight = computeWeight(n);
            if (weight > maxWeightFinal) {
                maxWeightFinal = weight;
            }
        }

        System.out.println(maxWeightFinal);
    }

    static long computeWeight(long n) {
        // Compute psi(n) by digit-wise complement
        // First, find the number of digits
        String s = Long.toString(n);
        int d = s.length();

        // Compute psi(n)
        long psi = 0;
        for (int i = 0; i < d; i++) {
            int digit = s.charAt(i) - '0';
            int complement = 9 - digit;
            psi = psi * 10 + complement;
        }

        return n * psi;
