        int digitsR = String.valueOf(r).length();

        for (int k = digitsL; k <= digitsR; k++) {
            long minK = (k == 1) ? 1 : (long) Math.pow(10, k - 1);
            long maxK = (long) Math.pow(10, k) - 1;

            // The ideal point for k-digit numbers (where first digit != 9) is (10^k - 1) / 2
            long ideal = (maxK) / 2;

            // Candidates around ideal
            for (long c = ideal - 2; c <= ideal + 2; c++) {
                if (c >= minK && c <= maxK) {
                    // Check if first digit is not 9
                    String s = String.valueOf(c);
                    if (s.charAt(0) != '9') {
                        candidates.add(c);
                    }
                }
            }

            // Also consider the boundaries of the k-digit range intersected with [l, r]
            long low = Math.max(l, minK);
            long high = Math.min(r, maxK);
            if (low <= high) {
                candidates.add(low);
                candidates.add(high);
            }
        }

        // Also, what if the optimal number has a first digit of 9?
        // If first digit is 9, then psi(n) has fewer digits.
        // For example, n = 9... (k digits). psi(n) = 0... (k-1 digits effectively).
        // The weight would be n * psi(n). Since psi(n) is much smaller, this is likely not the maximum
        // compared to numbers with first digit not 9, unless the range is very small and only contains such numbers.
        // But we already include l and r, and numbers around the ideal points.
        // Let's also add some numbers with first digit 9 if they are in the range, just in case.
        // Actually, the problem constraints are small enough that we can just check a few more candidates.

        // Let's refine: for each k, if the range [l, r] contains numbers with k digits,
        // we should check the numbers closest to the ideal point, and also the boundaries.

        // Let's just evaluate the weight for all candidates.
        long result = 0;
        for (long n : candidates) {
            if (n < l || n > r) continue;
            long psi = reflection(n);
            long weight = n * psi;
            if (weight > result) {
                result = weight;
            }
        }

        System.out.println(result);
    }

    static long reflection(long n) {
        if (n == 0) return 0;
        String s = String.valueOf(n);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            int d = s.charAt(i) - '0';
            sb.append(9 - d);
        }
        // Remove leading zeros
        String result = sb.toString();
        int i = 0;
        while (i < result.length() - 1 && result.charAt(i) == '0') {
            i++;
        }
        result = result.substring(i);
        return Long.parseLong(result);
    }
