            }
        }

        // Also, it might be good to check a few more points around the optimal
        // Let's just check all candidates
        for (long n : candidates) {
            if (n < l || n > r) continue;
            long weight = computeWeight(n);
            if (weight > maxWeight) {
                maxWeight = weight;
            }
        }

        System.out.println(maxWeight);
    }

    static long computeWeight(long n) {
