            if (half >= l && half <= r) candidates.add(half);
            long halfMinus1 = half - 1;
            if (halfMinus1 >= l && halfMinus1 <= r) candidates.add(halfMinus1);
            long halfPlus1 = half + 1;
            if (halfPlus1 >= l && halfPlus1 <= r) candidates.add(halfPlus1);
        }

        // Now evaluate the weight for each candidate
        for (long n : candidates) {
            if (n < l || n > r) continue;
            long psi = reflection(n);
            long weight = n * psi;
            if (weight > maxWeight) {
                maxWeight = weight;
            }
        }

        System.out.println(maxWeight);
    }

    static long reflection(long n) {
        if (n == 0) return 0;
        String s = Long.toString(n);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int digit = c - '0';
            int reflected = 9 - digit;
            sb.append(reflected);
        }
        // Remove leading zeros
        String result = sb.toString().replaceFirst("^0+", "");
        if (result.isEmpty()) return 0;
        return Long.parseLong(result);
    }
}
